#!/usr/bin/env bash
#
# check_dragon_golden.sh - the Spyro 1 dragon-rescue golden tier.
#
# One row per dragon rescue (80): the launch places Spyro above the statue,
# the landing triggers the rescue cutscene, and the row samples the dragon
# model, the cutscene camera path and its cuts on a 60-VBL grid from the
# trigger to the cutscene end, plus every cut VBL and the end VBL. Rows:
# games/spyro-1/corpus/dragon-rescue-corpus.manifest, generated by
# tools/gen_dragon_corpus.py from games/spyro-1/corpus/dragons.tsv. Golden:
# the verdict manifest tests/golden/spyro-1/dragons/blessed.tsv and its
# ident-baseline.tsv. Candidates are kept in build/dragon-candidate.
#
# The tier runs check_presentation_golden.sh with PRESENTATION_TIER=dragons:
# the same capture (canon, inter and ident legs, 16:9, llvmpipe), digest
# compare, identity check and bless, at stock LOD only (OPENPETE_CAP_LODS=original),
# with no freecam leg and no credits leg.
#
# Trigger policy. The tier is outside the `presentation` ctest label, so the
# default gate chains skip it. It runs:
#   - when a diff touches the sub-tick cut rule, the camera or moby capture
#     and re-extract path, cutscene handling, or the dragon and cutscene-actor
#     draw paths;
#   - at every release;
#   - on request.
# A dragon row that regresses is promoted into the presentation golden as a
# reported-row entry (its pins, canon and inter legs) in the change set that
# fixes it, blessed before the fix; the tier keeps its copy. Blessing follows
# the presentation golden's policy.
#
# The tiles are never committed (.gitignore); blessed.tsv and the identity
# baseline are. Every run compares the candidate's verdict digests against
# blessed.tsv; --bless rewrites the changed rows, files the tiles into the
# reference store and re-baselines the identity leg, as the presentation tier
# does.
#
# Usage:
#   tests/harness/check_dragon_golden.sh [--build-dir=DIR] [--filter=SUBSTR] [--bless]
#     --filter  row-name substring (<level>-<dragon>-<moby index>)
#     --bless   capture and promote every changed tile, rewrite the identity baseline
#
# Environment: CORPUS_JOBS (capture concurrency), PRESENTATION_GOLDEN_OUT
# (candidate directory), PRESENTATION_LEG_TIMEOUT (seconds per capture
# process, default 900 here: the ending-chain row runs 13197 VBLs).
#
# Exit: as check_presentation_golden.sh (0 match, 1 divergence / identity
# exceed / vacuous / missing manifest, 64 skip).
set -u
cd "$(dirname "$0")/../.."
export PRESENTATION_TIER=dragons
export OPENPETE_CAP_LODS=original
export PRESENTATION_LEG_TIMEOUT="${PRESENTATION_LEG_TIMEOUT:-900}"
for a in "$@"; do
  case "$a" in --game|--game=*) echo "check_dragon_golden: the tier is Spyro 1 only; --game is not accepted" >&2; exit 64;; esac
done
exec tests/harness/check_presentation_golden.sh "$@" --game=spyro-1
